SELECT 'g1' g, MIN(main_cat) a, MAX(main_cat) b FROM items_g1
UNION ALL SELECT 'g2', MIN(main_cat), MAX(main_cat) FROM items_g2
UNION ALL SELECT 'g3', MIN(main_cat), MAX(main_cat) FROM items_g3;

SELECT i.ref_id, i.rtg_ct, i.avg_rtg, COUNT(f.id) real_ct, ROUND(AVG(f.rtg),3) real_avg
FROM items_g3 i JOIN fdbk_g3 f ON f.ref_id=i.ref_id
GROUP BY i.ref_id LIMIT 10;

SELECT s.ref_id, s.review_ct, COUNT(f.id) c, ROUND(AVG(f.rtg),3) a
FROM fdbk_stats_g1 s LEFT JOIN fdbk_g1 f ON f.ref_id=s.ref_id
GROUP BY s.ref_id LIMIT 8;

SELECT 'g1' g, COUNT(*) n FROM items_g1 WHERE main_cat='All Electronics' AND prc>50 AND rtg_ct>=5 AND avg_rtg<3.0
UNION ALL SELECT 'g3', COUNT(*) FROM items_g3 WHERE main_cat='All Electronics' AND prc>50 AND rtg_ct>=5 AND avg_rtg<3.0
UNION ALL SELECT 'g1_stats', COUNT(*) FROM items_g1 i JOIN fdbk_stats_g1 s ON s.ref_id=i.ref_id WHERE i.main_cat='All Electronics' AND i.prc>50 AND s.review_ct>=5 AND s.avg_rtg<3.0;

WITH r AS (
  SELECT ref_id, COUNT(*) c, AVG(rtg) a FROM fdbk_g1 GROUP BY ref_id
) SELECT 'g1' g, COUNT(*) n FROM r JOIN items_g1 i ON i.ref_id=r.ref_id WHERE i.main_cat='All Electronics' AND i.prc>50 AND r.c>=5 AND r.a<3.0;

WITH r AS (
  SELECT ref_id, COUNT(*) c, AVG(rtg) a FROM fdbk_g3 GROUP BY ref_id
) SELECT 'g3' g, COUNT(*) n FROM r JOIN items_g3 i ON i.ref_id=r.ref_id WHERE i.main_cat='All Electronics' AND i.prc>50 AND r.c>=5 AND r.a<3.0;

WITH r AS (
  SELECT ref_id, COUNT(*) c, AVG(rtg) a FROM fdbk_g2 GROUP BY ref_id
) SELECT 'g2' g, COUNT(*) n FROM r JOIN items_g2 i ON i.ref_id=r.ref_id WHERE i.main_cat='All Electronics' AND i.prc_usd>50 AND r.c>=5 AND r.a<3.0;

SELECT
 (SELECT COUNT(*) FROM items_g1 i WHERE i.ref_id NOT IN (SELECT ref_id FROM fdbk_stats_g1) AND EXISTS(SELECT 1 FROM fdbk_g1 f WHERE f.ref_id=i.ref_id)) nonstats_with_fdbk,
 (SELECT COUNT(*) FROM items_g1 i WHERE i.ref_id IN (SELECT ref_id FROM fdbk_stats_g1)) stats_items;
